    jauge: {"style":"Languedoc-Roussillon, rouge","acidite":5,"tanins":5,"src":"WSET D3, Wines of the World (2024) ; Oxford Companion to Wine (2023) ; WSET, Understanding Wines (2016) ; Wine Grapes (2012)"},
